        cells=[(r,j) for r in range(h) for j in range(w) if grid[r][j]==c]
        if cells: comps.append((c,cells))
    if all(len(x[1])==1 for x in comps):
        target=min(r for c,cs in comps for r,j in cs)
    else:
        target=max(max(r for r,j in cs) for c,cs in comps)
    out=[[0]*w for _ in range(h)]
    for c,cells in comps:
        shift=target-max(r for r,j in cells)
        for r,j in cells:
            rr=r+shift
            if 0<=rr<h: out[rr][j]=c
    return out"}

