{"code":"def transform(grid):
    h=len(grid); w=len(grid[0])
    colors=set(x for r in grid for x in r if x)
    comps=[]
    for c in colors:
        cells=[(i,j) for i in range(h) for j in range(w) if grid[i][j]==c]
        if cells: comps.append((c,cells))
    # canonical alignment: multi-cell block-like objects share their lowest edge;
    # isolated singletons are placed on the top edge.
    multi=[x for x in comps if len(x[1])>1]
    out=[[0]*w for _ in range(h)]
    if multi:
        target=max(max(i for i,j in cells) for c,cells in multi)
        for c,cells in comps:
            if len(cells)==1:
                shift=-min(i for i,j in cells)
            else:
                shift=target-max(i for i,j in cells)
            for i,j in cells:
                ni=i+shift
                if 0<=ni<h: out[ni][j]=c
    else:
        for c,cells in comps:
            i,j=cells[0]; out[0][j]=c
    return out"}

